double fn0(List<int> sortedLogDurations, int k) {
  if (sortedLogDurations.isEmpty) return -1.0;
  int lo = 0;
  int hi = sortedLogDurations.length - 1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (sortedLogDurations[mid] >= k) {
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }
  if (lo < sortedLogDurations.length) {
    return sortedLogDurations[lo].toDouble();
  } else {
    return -1.0;
  }
}

