int fn0(List<int> requests) {
  var stack = <int>[];
  for (var r in requests) {
    if (r == 0) {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(r);
    }
  }
  var total = 0;
  for (var v in stack) total += v;
  return total;
}

@pragma('vm:never-inline')
