String fn0(List<int> pricesCents) {
  Map<String, int> dirs = {'up':0,'down':0,'none':0};
  for (var p in pricesCents) {
    int rem = p % 5;
    if (rem == 0) dirs['none'] = dirs['none']!+1;
    else if (rem < 3) dirs['down'] = dirs['down']!+1;
    else dirs['up'] = dirs['up']!+1;
  }
  return 'up:${dirs['up']}, down:${dirs['down']}, none:${dirs['none']}';
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

String fn0(List<int> cents) {
  int l = 0, r = cents.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (cents[m] < 50) l = m + 1;
    else r = m;
  }
  return l == cents.length ? 'all-down' : '${cents[l]}c';
}

@pragma('vm:never-inline')
