bool fn0(List<List<int>> grid) {
  if (grid.length < 2) return true;
  for (int i = 1; i < grid.length; i++) {
    List<int> row1 = grid[i - 1];
    List<int> row2 = grid[i];
    int dx = (row1[0] - row2[0]).abs();
    int dy = (row1[1] - row2[1]).abs();
    if (dx + dy > 5) return false;
  }
  return true;
}

