List<int> fn0(String signal) {
  List<int> bins = [];
  for (int i = 0; i < signal.length; i += 2) {
    bins.addAll(List.filled(int.parse(signal[i + 1]), signal.codeUnitAt(i)));
  }
  return bins;
}

