List<int> fn0(String playlist) {
  if (playlist.isEmpty) return [];
  List<int> result = [];
  for (var track in playlist.split(',')) {
    int i = track.indexOf(':');
    int minute = int.parse(track.substring(i + 1));
    result.add(minute);
  }
  return result;
}

