String fn0(List<int> minutes) {
  List<int> sorted = List<int>.from(minutes);
  sorted.sort((a, b) {
    int diffA = (a - 45).abs();
    int diffB = (b - 45).abs();
    if (diffA != diffB) return diffA.compareTo(diffB);
    return a.compareTo(b);
  });
  return sorted.join(',');
}

